const socket = new WebSocket('wss://example.com/chat');

socket.addEventListener('open', () => {
  // This event fires ONLY after the server's 101 response has been
  // received and the handshake has genuinely, fully succeeded
  console.log('Handshake complete - now exchanging frames, not HTTP requests');
});

socket.addEventListener('message', (event) => {
  // Each invocation of this handler corresponds to one genuine
  // WebSocket TEXT or BINARY frame having arrived - not a new HTTP
  // request/response cycle of any kind
  console.log('Received frame data:', event.data);
});

