After installing (npm install socket.io on the server, socket.io-client on the frontend), setting up the server:

import { Server } from 'socket.io';

const io = new Server(httpServer);

io.on('connection', (socket) => {
  console.log('A user connected:', socket.id);

  // ROOMS - joining a specific, named group, rather than broadcasting
  // to literally every connected user
  socket.on('join-room', (roomId: string) => {
    socket.join(roomId);
  });

  // CUSTOM EVENTS - genuinely different message types, each handled
  // by its own specifically-named listener, replacing lesson 1's
  // single undifferentiated 'message' event entirely
  socket.on('chat-message', (data: { roomId: string; text: string }) => {
    // io.to(roomId) targets ONLY clients who have joined that
    // specific room, not every connected client
    io.to(data.roomId).emit('new-message', { text: data.text, senderId: socket.id });
  });

  socket.on('disconnect', () => {
    console.log('User disconnected:', socket.id);
  });
});

The corresponding frontend client:

import { io } from 'socket.io-client';

const socket = io('https://example.com');

socket.emit('join-room', 'general');

socket.on('new-message', (data) => {
  console.log(`${data.senderId}: ${data.text}`);
});

socket.emit('chat-message', { roomId: 'general', text: 'Hello!' });

