import { Server } from 'socket.io';

const io = new Server(httpServer, {
  // Socket.io automatically attempts reconnection by default if a
  // connection drops - this configuration just tunes the specific
  // retry behavior, rather than needing to implement it from scratch
  reconnectionAttempts: 5,
  reconnectionDelay: 1000
});

io.on('connection', (socket) => {
  socket.on('join-room', (roomId: string) => {
    socket.join(roomId);

    // Broadcasting to EVERYONE ELSE in this room specifically -
    // socket.to() (not io.to()) excludes the sender themselves,
    // a genuinely useful, common targeting pattern
    socket.to(roomId).emit('user-joined', { userId: socket.id });
  });

  socket.on('leave-room', (roomId: string) => {
    socket.leave(roomId);
    socket.to(roomId).emit('user-left', { userId: socket.id });
  });

  socket.on('chat-message', (data: { roomId: string; text: string }) => {
    // io.to() includes EVERYONE in the room, including the sender -
    // appropriate here since the sender should also see their own
    // message appear, exactly as a real chat application needs
    io.to(data.roomId).emit('new-message', { text: data.text, senderId: socket.id });
  });
});

// Frontend - automatic reconnection requires NO manual code at all;
// Socket.io handles detecting the drop and re-establishing the
// connection transparently, including automatically re-joining any
// rooms IF the application re-runs its own join-room logic on 'connect'
socket.on('connect', () => {
  socket.emit('join-room', 'general'); // re-joins automatically every
    // time a connection is established, including after a reconnect
});

