Showing a chat message immediately, before the server has genuinely confirmed it, then reconciling once confirmation (or a failure) actually arrives:

function ChatRoom() {
  const [messages, setMessages] = useState<Message[]>([]);

  function sendMessage(text: string) {
    const optimisticMessage: Message = {
      id: `temp-${Date.now()}`, // a TEMPORARY, client-generated id,
                                   // clearly distinct from a genuine,
                                   // server-assigned one
      text,
      status: 'sending', // explicitly tracked, distinct from 'sent'
      senderId: currentUserId
    };

    // Show it IMMEDIATELY, optimistically, before any server
    // confirmation has actually arrived
    setMessages((prev) => [...prev, optimisticMessage]);

    socket.emit('chat-message', { text }, (serverConfirmedMessage: Message) => {
      // RECONCILIATION - replace the temporary, optimistic message
      // with the server's genuine, authoritative version, once it
      // actually arrives
      setMessages((prev) =>
        prev.map((m) => (m.id === optimisticMessage.id ? serverConfirmedMessage : m))
      );
    });
  }

  // ...
}

