import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect } from 'react';

function ChatRoom({ roomId }: { roomId: string }) {
  const queryClient = useQueryClient();

  // The room's MESSAGE HISTORY - genuinely request-response shaped
  // data (Module 16 lesson 4's exact territory), fetched once via
  // React Query, NOT delivered via the WebSocket connection at all
  const { data: messageHistory } = useQuery({
    queryKey: ['messages', roomId],
    queryFn: () => fetch(`/api/rooms/${roomId}/messages`).then((r) => r.json())
  });

  // NEW, incoming messages, arriving via the WebSocket connection -
  // genuinely push-based, exactly Module 17 lesson 5's category,
  // which React Query was never designed for
  useEffect(() => {
    socket.on('new-message', (message: Message) => {
      // Directly updating React Query's own cache with the newly
      // arrived realtime message, rather than maintaining a
      // genuinely separate, second copy of this same data
      queryClient.setQueryData(['messages', roomId], (old: Message[] = []) => [
        ...old,
        message
      ]);
    });

    return () => socket.off('new-message');
  }, [roomId, queryClient]);

  return <MessageList messages={messageHistory ?? []} />;
}

