codingChallenge.solutionExample:
interface Todo {
  id: string;
  text: string;
  status: 'saving' | 'saved' | 'failed';
}

function useTodos() {
  const [todos, setTodos] = useState<Todo[]>([]);

  async function addTodoOptimistically(text: string) {
    const tempId = `temp-${Date.now()}`;
    const optimisticTodo: Todo = { id: tempId, text, status: 'saving' };

    setTodos((prev) => [...prev, optimisticTodo]);

    try {
      const response = await fetch('/api/todos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text })
      });
      if (!response.ok) throw new Error('Failed to save todo');
      const savedTodo = await response.json();

      setTodos((prev) =>
        prev.map((t) => (t.id === tempId ? { ...savedTodo, status: 'saved' } : t))
      );
    } catch (err) {
      setTodos((prev) =>
        prev.map((t) => (t.id === tempId ? { ...t, status: 'failed' } : t))
      );
    }
  }

  return { todos, addTodoOptimistically };
}

