Authenticating a Socket.io connection using Module 9's existing JWT, verified during the connection handshake itself:

import jwt from 'jsonwebtoken';

io.use((socket, next) => {
  const token = socket.handshake.auth.token; // sent by the client
                                                // during connection setup
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as { userId: string };
    socket.data.userId = decoded.userId; // attached directly to this
                                            // specific socket connection,
                                            // available in every later
                                            // event handler for it
    next();
  } catch (err) {
    next(new Error('Authentication failed'));
  }
});

io.on('connection', (socket) => {
  socket.on('join-room', async (roomId: string) => {
    socket.join(roomId);

    // Loading PERSISTED message history from MongoDB (Module 19),
    // sent ONLY to the joining client, not broadcast to the room
    const history = await messagesCollection
      .find({ roomId })
      .sort({ createdAt: 1 })
      .limit(50)
      .toArray();
    socket.emit('message-history', history);
  });

  socket.on('chat-message', async (data: { roomId: string; text: string }) => {
    const message = {
      roomId: data.roomId,
      text: data.text,
      senderId: socket.data.userId, // the AUTHENTICATED user's id,
                                       // never trusted from the client
                                       // payload itself
      createdAt: new Date()
    };

    const result = await messagesCollection.insertOne(message);
    io.to(data.roomId).emit('new-message', { ...message, _id: result.insertedId });
  });
});

