import { io } from 'socket.io-client';
import { useEffect, useState } from 'react';

function ChatRoom({ roomId, authToken }: { roomId: string; authToken: string }) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [socket, setSocket] = useState<ReturnType<typeof io> | null>(null);

  useEffect(() => {
    const newSocket = io('https://example.com', {
      auth: { token: authToken } // sent during the handshake, verified
                                    // by this lesson's server-side
                                    // middleware before any connection
                                    // is genuinely established
    });

    newSocket.on('connect', () => {
      newSocket.emit('join-room', roomId); // lesson 2's reconnection-
                                              // safe re-join pattern
    });

    newSocket.on('message-history', (history: Message[]) => {
      setMessages(history); // the room's persisted past, loaded once
    });

    newSocket.on('new-message', (message: Message) => {
      setMessages((prev) => {
        // RECONCILIATION (lesson 3) - if this confirms our OWN
        // optimistic message, replace it; otherwise, it's a
        // genuinely new message from someone else, so append it
        const optimisticIndex = prev.findIndex((m) => m.id === message.tempId);
        if (optimisticIndex !== -1) {
          const updated = [...prev];
          updated[optimisticIndex] = message;
          return updated;
        }
        return [...prev, message];
      });
    });

    setSocket(newSocket);
    return () => newSocket.close(); // Module 17 lesson 5's cleanup discipline
  }, [roomId, authToken]);

  function sendMessage(text: string) {
    const tempId = `temp-${Date.now()}`;
    setMessages((prev) => [...prev, { tempId, text, status: 'sending' } as Message]);
    socket?.emit('chat-message', { roomId, text, tempId });
  }

  return <MessageList messages={messages} onSend={sendMessage} />;
}

