sections.content:
Presence, correctly counting connections per user rather than naively treating any single disconnect as 'this user is now offline':

const userConnectionCounts = new Map<string, number>(); // userId ->
                                                            // number of
                                                            // currently
                                                            // active connections

io.on('connection', (socket) => {
  const userId = socket.data.userId;
  const currentCount = userConnectionCounts.get(userId) ?? 0;
  userConnectionCounts.set(userId, currentCount + 1);

  if (currentCount === 0) {
    // This is genuinely their FIRST active connection - only NOW do
    // they transition from offline to online
    io.emit('user-online', { userId });
  }

  socket.on('disconnect', () => {
    const newCount = (userConnectionCounts.get(userId) ?? 1) - 1;
    userConnectionCounts.set(userId, newCount);

    if (newCount === 0) {
      // Genuinely their LAST connection just closed - only NOW do
      // they transition from online to offline
      io.emit('user-offline', { userId });
    }
  });
});

Routing a notification to a specific user across ALL of their
currently active connections, using Socket.io's per-user room convention:

io.on('connection', (socket) => {
  socket.join(`user:${socket.data.userId}`); // every connection a
    // specific user has joins this SAME personal room automatically
});

function notifyUser(userId: string, notification: Notification) {
  io.to(`user:${userId}`).emit('notification', notification); // reaches
    // EVERY active connection this specific user currently has, whether
    // that's one connection or several simultaneously
}

