const userConnectionCounts = new Map<string, number>();

io.on('connection', (socket) => {
  const userId = socket.data.userId;

  // Join this user's personal notification room (lesson's notification
  // mechanism), regardless of how many OTHER connections they already have
  socket.join(`user:${userId}`);

  // Presence counting (this lesson's first mechanism)
  const currentCount = userConnectionCounts.get(userId) ?? 0;
  userConnectionCounts.set(userId, currentCount + 1);
  if (currentCount === 0) {
    io.emit('user-online', { userId });
  }

  socket.on('disconnect', () => {
    const newCount = (userConnectionCounts.get(userId) ?? 1) - 1;
    userConnectionCounts.set(userId, newCount);
    if (newCount === 0) {
      io.emit('user-offline', { userId });
    }
    // NOTE: we do NOT need to manually socket.leave() the personal
    // room here - Socket.io automatically removes a disconnected
    // socket from every room it had joined
  });
});

// Triggered from anywhere else in the application - a new comment
// on a post the user is following, for instance
